.circle-highlight-seat:hover {
    transform: scale(1.08);
}
.seat-red-circle {
    display: none;
    position: absolute;
    inset: -6px -10px;
    border: 4px solid #E53935;
    border-radius: 24px;
    transform: rotate(-6deg);
    animation: drawCircle 0.35s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
    pointer-events: none;
    box-shadow: 0 0 10px rgba(229, 57, 53, 0.4);
}
@keyframes drawCircle {
    0% { transform: scale(0.5) rotate(-20deg); opacity: 0; }
    60% { transform: scale(1.15) rotate(-4deg); opacity: 1; }
    100% { transform: scale(1.05) rotate(-6deg); opacity: 1; }
}

.pop-in-soft { animation: popInSoft 0.25s cubic-bezier(0.34, 1.56, 0.64, 1) forwards; }"

